-- Создание индекса в PostgreSQL/Greenplum
CREATE INDEX idx_sales_date ON sales (sale_date);
CREATE INDEX idx_sales_date_category ON sales (sale_date, category);
CREATE INDEX idx_sales_status ON sales USING bitmap (status);

-- Пример SCD Type 2
BEGIN;
LOCK TABLE dim_customer IN EXCLUSIVE MODE;
UPDATE dim_customer SET end_date = current_date, is_current = false
WHERE customer_id IN (SELECT id FROM source_updates) AND is_current = true;
INSERT INTO dim_customer SELECT *, current_date, '9999-12-31', true FROM source_updates;
COMMIT;
